builder.Services.AddExceptionHandler<DomainExceptionHandler>();
builder.Services.AddProblemDetails();

var app = builder.Build();
app.UseExceptionHandler();            // before routing/health so nothing escapes
// app.UseExceptionHandler("/error"); // classic re-execution alternative
app.UseStatusCodePages();             // 404/401 without a body get one too

// One handler per family of failures
class DomainExceptionHandler : IExceptionHandler
{
    private readonly ILogger<DomainExceptionHandler> _log;

    public async ValueTask<bool> TryHandleAsync(
        HttpContext ctx, Exception ex, CancellationToken ct)
    {
        var (status, title) = ex switch
        {
            NotFoundException     => (StatusCodes.Status404NotFound, "Not Found"),
            ConflictException     => (StatusCodes.Status409Conflict, "Conflict"),
            FluentValidationException v => (StatusCodes.Status400BadRequest, "Validation Failed"),
            OperationCanceledException when ctx.RequestAborted.IsCancellationRequested
                                      => (499, "Client Closed Request"),
            _ => (StatusCodes.Status500InternalServerError, "Server Error")
        };

        _log.LogError(ex, "Unhandled {ExceptionType} on {Path} (trace {TraceId})",
            ex.GetType().Name, ctx.Request.Path, ctx.TraceIdentifier);

        await Results.Problem(
            statusCode: status,
            title: title,
            detail: status == 500 ? "An unexpected error occurred." : ex.Message,
            extensions: new Dictionary<string, object?>
            {
                ["traceId"] = ctx.TraceIdentifier
            }).ExecuteAsync(ctx);

        return true;    // handled — exception will not propagate
    }
}
